local ServicesTicker = require(script.Parent.Parent.Parent.Core.Misc.ServicesTicker)

local PlayerHostedServiceManager = {}
PlayerHostedServiceManager.__index = PlayerHostedServiceManager

function PlayerHostedServiceManager.new(player: Player, playerHosts: IEnumerable<IPlayerHostedService>)
	local self = setmetatable({}, PlayerHostedServiceManager)
	self._player = player
	self._hostedServices = playerHosts
	self._servicesTicker = ServicesTicker.new(playerHosts)
	return self
end

function PlayerHostedServiceManager:Start(cancellationToken: CancellationToken)
	for _, service in self._hostedServices do
		if cancellationToken.IsCancellationRequested then
			return
		end
		if service.Start then
			service:Start(cancellationToken)
		end
	end
	self._servicesTicker:Start(cancellationToken)
end

function PlayerHostedServiceManager:Stop()
	if self._servicesTicker then
		self._servicesTicker:Stop()
	end
	if self._hostedServices then
		for _, service in self._hostedServices do
			if service.Stop then
				service:Stop()
			end
		end
	end
end

return PlayerHostedServiceManager
